/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Cbrt, Float, Lt, Mul, Pow, S, Sqrt, Sym, diff, exp, exp2, expandLog, expm1, fma, hypot, isUnsolved, isinf, isnan, log, log10, log1p, log2, nan, oo, pi, rational, symbols } from '../../src';
import { sympyStr } from '../sympy-str';
import { equivalent } from '../sympy-equivalent';

describe("doctests of sympy.codegen.cfunctions", () => {
  it("Cbrt(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(Cbrt(x))).toBe('Cbrt(x)');
  });
  it("Cbrt(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(Cbrt(x), x))).toBe('1/(3*x**(2/3))');
  });
  it("Sqrt(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(Sqrt(x))).toBe('Sqrt(x)');
  });
  it("Sqrt(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(Sqrt(x), x))).toBe('1/(2*sqrt(x))');
  });
  it("exp2(2).evalf() == 4.0", () => {
    expect(sympyStr(new Float({ man: 1n, exp: 2n }, 53).equals(new Float(4)))).toBe('True');
  });
  it("exp2(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(exp2(x), x))).toBe('log(2)*exp2(x)');
  });
  // printed with a Python number format
  //   '%.0e' % expm1(1e-99).evalf()
  //   => 1e-99
  it.todo("'%.0e' % expm1(1e-99).evalf()");
  it("expm1(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(expm1(x), x))).toBe('exp(x)');
  });
  it("fma(x, y, z).diff(x)", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(diff(fma(x, y, z), x))).toBe('y');
  });
  it("hypot(3, 4).evalf() == 5.0", () => {
    expect(sympyStr(new Float({ man: 5n, exp: 0n }, 53).equals(new Float(5)))).toBe('True');
  });
  it("hypot(x, y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(hypot(x, y))).toBe('hypot(x, y)');
  });
  it("hypot(x, y).diff(x)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(diff(hypot(x, y), x))).toBe('x/hypot(x, y)');
  });
  it("log10(100).evalf() == 2.0", () => {
    expect(sympyStr(new Float({ man: 1n, exp: 1n }, 53).equals(new Float(2)))).toBe('True');
  });
  it("log10(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(log10(x), x))).toBe('1/(x*log(10))');
  });
  // printed with a Python number format
  //   '%.0e' % expand_log(log1p(1e-99)).evalf()
  //   => 1e-99
  it.todo("'%.0e' % expand_log(log1p(1e-99)).evalf()");
  it("log1p(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(log1p(x), x))).toBe('1/(x + 1)');
  });
  it("log2(4).evalf() == 2.0", () => {
    expect(sympyStr(new Float({ man: 1n, exp: 1n }, 53).equals(new Float(2)))).toBe('True');
  });
  it("log2(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(log2(x), x))).toBe('1/(x*log(2))');
  });
});

